static int hex(const char *value,size_t size){if(!value||strlen(value)!=size)return 0;for(size_t i=0;i<size;i++)if(!((value[i]>='0'&&value[i]<='9')||(value[i]>='a'&&value[i]<='f')))return 0;return 1;}
static int uuid(const char *value){if(!value||strlen(value)!=36)return 0;for(size_t i=0;i<36;i++){if(i==8||i==13||i==18||i==23){if(value[i]!='-')return 0;}else if(!((value[i]>='0'&&value[i]<='9')||(value[i]>='a'&&value[i]<='f')))return 0;}return value[14]>='1'&&value[14]<='8'&&strchr("89ab",value[19]);}
static int handle(const char *value){size_t size=value?strlen(value):0;if(size<23||size>120||memcmp(value,"tra:v1:",7))return 0;for(size_t i=7;i<size;i++)if(!((value[i]>='A'&&value[i]<='Z')||(value[i]>='a'&&value[i]<='z')||(value[i]>='0'&&value[i]<='9')||strchr("_:-",value[i])))return 0;return 1;}
static int site(const char *value){size_t size=value?strlen(value):0;if(!size||size>63||value[0]<'a'||value[0]>'z')return 0;for(size_t i=1;i<size;i++)if(!((value[i]>='a'&&value[i]<='z')||(value[i]>='0'&&value[i]<='9')||value[i]=='-'))return 0;return 1;}
static int u64(const char *value,uint64_t *output){if(!value||!*value||(value[0]=='0'&&value[1]))return 0;uint64_t result=0;for(const char *p=value;*p;p++){if(*p<'0'||*p>'9')return 0;unsigned d=(unsigned)(*p-'0');if(result>(UINT64_MAX-d)/10u)return 0;result=result*10u+d;}*output=result;return 1;}
static int next(const char **cursor,const char *end,const char *key,char *output,size_t capacity){size_t key_size=strlen(key);const char *start=*cursor;if((size_t)(end-start)<=key_size||memcmp(start,key,key_size))return 0;start+=key_size;const char *newline=memchr(start,'\n',(size_t)(end-start));size_t size=newline?(size_t)(newline-start):capacity;if(!newline||!size||size>=capacity||memchr(start,0,size))return 0;memcpy(output,start,size);output[size]=0;*cursor=newline+1;return 1;}
static int next_u64(const char **cursor,const char *end,const char *key,uint64_t *output){char value[32];return next(cursor,end,key,value,sizeof(value))&&u64(value,output);}
static int parse_operation(const char *operation,const char *role,enum rtew_v4_operation *o,enum rtew_v4_role *r){if(!strcmp(operation,"INSPECT_TARGET")&&!strcmp(role,"NONE")){*o=RTEW_V4_INSPECT_TARGET;*r=RTEW_V4_NONE;}else if(!strcmp(operation,"ENSURE_INTERNAL_NETWORK")&&!strcmp(role,"NETWORK")){*o=RTEW_V4_ENSURE_INTERNAL_NETWORK;*r=RTEW_V4_NETWORK;}else if(!strcmp(operation,"CREATE_POSTGRES")&&!strcmp(role,"POSTGRES")){*o=RTEW_V4_CREATE_POSTGRES;*r=RTEW_V4_POSTGRES;}else if(!strcmp(operation,"CREATE_MINIO")&&!strcmp(role,"MINIO")){*o=RTEW_V4_CREATE_MINIO;*r=RTEW_V4_MINIO;}else return 0;return 1;}
static const char *operation(enum rtew_v4_operation value){switch(value){case RTEW_V4_INSPECT_TARGET:return"INSPECT_TARGET";case RTEW_V4_ENSURE_INTERNAL_NETWORK:return"ENSURE_INTERNAL_NETWORK";case RTEW_V4_CREATE_POSTGRES:return"CREATE_POSTGRES";case RTEW_V4_CREATE_MINIO:return"CREATE_MINIO";}return NULL;}
static const char *role(enum rtew_v4_role value){switch(value){case RTEW_V4_NONE:return"NONE";case RTEW_V4_NETWORK:return"NETWORK";case RTEW_V4_POSTGRES:return"POSTGRES";case RTEW_V4_MINIO:return"MINIO";}return NULL;}
static int valid_command(const struct rtew_command_v4 *v){return v&&operation(v->operation)&&role(v->role)&&((v->operation==RTEW_V4_INSPECT_TARGET&&v->role==RTEW_V4_NONE)||(v->operation==RTEW_V4_ENSURE_INTERNAL_NETWORK&&v->role==RTEW_V4_NETWORK)||(v->operation==RTEW_V4_CREATE_POSTGRES&&v->role==RTEW_V4_POSTGRES)||(v->operation==RTEW_V4_CREATE_MINIO&&v->role==RTEW_V4_MINIO))&&uuid(v->installation_id)&&site(v->site_id)&&uuid(v->host_installation_id)&&uuid(v->operation_id)&&handle(v->target_handle)&&v->generation&&v->supervisor_generation&&v->deadline_unix_ms&&hex(v->acquired_request_sha256,64)&&hex(v->profile_v4_sha256,64)&&hex(v->resource_admission_v3_sha256,64)&&hex(v->credential_admission_receipt_sha256,64)&&hex(v->credential_use_witness_sha256,64)&&hex(v->authority_instance_sha256,64)&&hex(v->challenge_nonce,32)&&hex(v->command_nonce,32)&&strcmp(v->challenge_nonce,v->command_nonce)&&hex(v->materialization_head_sha256,64)&&hex(v->asset_manifest_sha256,64);}
int rtew_parse_command_v4(const void *bytes,size_t size,struct rtew_command_v4 *v){if(!bytes||!v||!size||size>RTEW_V4_MAX_BYTES||((const char*)bytes)[size-1]!='\n'||memchr(bytes,'\r',size)||memchr(bytes,0,size)){errno=EPROTO;return-1;}memset(v,0,sizeof(*v));const char *p=bytes,*end=p+size;char format[64],op[32],r[16];if(!next(&p,end,"format=",format,sizeof(format))||strcmp(format,"darshan-recovery-target-native-engine-command-v4")||!next(&p,end,"operation=",op,sizeof(op))||!next(&p,end,"role=",r,sizeof(r))||!next(&p,end,"installation_id=",v->installation_id,sizeof(v->installation_id))||!next(&p,end,"site_id=",v->site_id,sizeof(v->site_id))||!next(&p,end,"host_installation_id=",v->host_installation_id,sizeof(v->host_installation_id))||!next(&p,end,"operation_id=",v->operation_id,sizeof(v->operation_id))||!next(&p,end,"target_handle=",v->target_handle,sizeof(v->target_handle))||!next_u64(&p,end,"generation=",&v->generation)||!next(&p,end,"acquired_request_sha256=",v->acquired_request_sha256,65)||!next(&p,end,"profile_v4_sha256=",v->profile_v4_sha256,65)||!next(&p,end,"resource_admission_v3_sha256=",v->resource_admission_v3_sha256,65)||!next(&p,end,"credential_admission_receipt_sha256=",v->credential_admission_receipt_sha256,65)||!next(&p,end,"credential_use_witness_sha256=",v->credential_use_witness_sha256,65)||!next(&p,end,"authority_instance_sha256=",v->authority_instance_sha256,65)||!next_u64(&p,end,"supervisor_generation=",&v->supervisor_generation)||!next(&p,end,"challenge_nonce=",v->challenge_nonce,33)||!next(&p,end,"command_nonce=",v->command_nonce,33)||!next(&p,end,"materialization_head_sha256=",v->materialization_head_sha256,65)||!next_u64(&p,end,"deadline_unix_ms=",&v->deadline_unix_ms)||!next(&p,end,"asset_manifest_sha256=",v->asset_manifest_sha256,65)||p!=end||!parse_operation(op,r,&v->operation,&v->role)||!valid_command(v)){errno=EPROTO;return-1;}return 0;}
int rtew_encode_command_v4(const struct rtew_command_v4 *v,void *bytes,size_t capacity,size_t *size){if(!bytes||!size||!valid_command(v)){errno=EINVAL;return-1;}int n=snprintf(bytes,capacity,"format=darshan-recovery-target-native-engine-command-v4\noperation=%s\nrole=%s\ninstallation_id=%s\nsite_id=%s\nhost_installation_id=%s\noperation_id=%s\ntarget_handle=%s\ngeneration=%llu\nacquired_request_sha256=%s\nprofile_v4_sha256=%s\nresource_admission_v3_sha256=%s\ncredential_admission_receipt_sha256=%s\ncredential_use_witness_sha256=%s\nauthority_instance_sha256=%s\nsupervisor_generation=%llu\nchallenge_nonce=%s\ncommand_nonce=%s\nmaterialization_head_sha256=%s\ndeadline_unix_ms=%llu\nasset_manifest_sha256=%s\n",operation(v->operation),role(v->role),v->installation_id,v->site_id,v->host_installation_id,v->operation_id,v->target_handle,(unsigned long long)v->generation,v->acquired_request_sha256,v->profile_v4_sha256,v->resource_admission_v3_sha256,v->credential_admission_receipt_sha256,v->credential_use_witness_sha256,v->authority_instance_sha256,(unsigned long long)v->supervisor_generation,v->challenge_nonce,v->command_nonce,v->materialization_head_sha256,(unsigned long long)v->deadline_unix_ms,v->asset_manifest_sha256);if(n<=0||(size_t)n>=capacity||(size_t)n>RTEW_V4_MAX_BYTES){errno=EMSGSIZE;return-1;}*size=(size_t)n;return 0;}
static int hash_domain(const char *domain,const void *bytes,size_t size,char output[65]){int alg=socket(AF_ALG,SOCK_SEQPACKET|SOCK_CLOEXEC,0);if(alg<0)return-1;struct sockaddr_alg address={.salg_family=AF_ALG,.salg_type="hash",.salg_name="sha256"};if(bind(alg,(struct sockaddr*)&address,sizeof(address))<0){int e=errno;close(alg);errno=e;return-1;}int op=accept4(alg,NULL,NULL,SOCK_CLOEXEC);close(alg);if(op<0)return-1;struct iovec parts[2]={{.iov_base=(void*)domain,.iov_len=strlen(domain)+1},{.iov_base=(void*)bytes,.iov_len=size}};struct msghdr message={.msg_iov=parts,.msg_iovlen=2};if(sendmsg(op,&message,0)!=(ssize_t)(strlen(domain)+1+size)){int e=errno?errno:EIO;close(op);errno=e;return-1;}unsigned char digest[32];if(read(op,digest,32)!=32){close(op);errno=EIO;return-1;}close(op);static const char h[]="0123456789abcdef";for(size_t i=0;i<32;i++){output[i*2]=h[digest[i]>>4];output[i*2+1]=h[digest[i]&15];}output[64]=0;return 0;}
int rtew_command_wire_sha256_v4(const void *bytes,size_t size,char output[65]){struct rtew_command_v4 command;if(rtew_parse_command_v4(bytes,size,&command)<0)return-1;return hash_domain("darshan-recovery-target-native-engine-command-wire-v4",bytes,size,output);}
int rtew_command_semantic_sha256_v4(const struct rtew_command_v4 *v,char output[65]){if(!valid_command(v)||!output){errno=EINVAL;return-1;}char bytes[RTEW_V4_MAX_BYTES];int n=snprintf(bytes,sizeof(bytes),"domain=darshan-recovery-target-native-engine-command-semantic-v4\noperation=%s\nrole=%s\ninstallation_id=%s\nsite_id=%s\nhost_installation_id=%s\noperation_id=%s\ntarget_handle=%s\ngeneration=%llu\nacquired_request_sha256=%s\nprofile_v4_sha256=%s\nresource_admission_v3_sha256=%s\ncredential_admission_receipt_sha256=%s\ncredential_use_witness_sha256=%s\nauthority_instance_sha256=%s\nsupervisor_generation=%llu\nchallenge_nonce=%s\ncommand_nonce=%s\nmaterialization_head_sha256=%s\ndeadline_unix_ms=%llu\nasset_manifest_sha256=%s\n",operation(v->operation),role(v->role),v->installation_id,v->site_id,v->host_installation_id,v->operation_id,v->target_handle,(unsigned long long)v->generation,v->acquired_request_sha256,v->profile_v4_sha256,v->resource_admission_v3_sha256,v->credential_admission_receipt_sha256,v->credential_use_witness_sha256,v->authority_instance_sha256,(unsigned long long)v->supervisor_generation,v->challenge_nonce,v->command_nonce,v->materialization_head_sha256,(unsigned long long)v->deadline_unix_ms,v->asset_manifest_sha256);if(n<=0||(size_t)n>=sizeof(bytes)){errno=EMSGSIZE;return-1;}return hash_domain("darshan-recovery-target-native-engine-command-semantic-digest-v4",bytes,(size_t)n,output);}
static int valid_inspection(const struct rtew_inspection_v4 *v){return v&&operation(v->operation)&&role(v->role)&&uuid(v->operation_id)&&handle(v->target_handle)&&v->generation&&v->supervisor_generation&&hex(v->command_semantic_sha256,64)&&hex(v->command_wire_sha256,64)&&hex(v->command_nonce,32)&&hex(v->authority_instance_sha256,64)&&hex(v->challenge_nonce,32)&&hex(v->materialization_head_sha256,64)&&hex(v->asset_manifest_sha256,64)&&hex(v->daemon_identity_sha256,64)&&hex(v->daemon_response_sha256,64)&&v->observation_complete&&hex(v->network_projection_sha256,64)&&hex(v->postgres_projection_sha256,64)&&hex(v->minio_projection_sha256,64);}
int rtew_parse_inspection_v4(const void *bytes,size_t size,struct rtew_inspection_v4 *v){if(!bytes||!v||!size||size>RTEW_V4_MAX_BYTES||((const char*)bytes)[size-1]!='\n'||memchr(bytes,'\r',size)||memchr(bytes,0,size)){errno=EPROTO;return-1;}memset(v,0,sizeof(*v));const char *p=bytes,*end=p+size;char format[64],op[32],r[16],complete[8],absence[8];if(!next(&p,end,"format=",format,sizeof(format))||strcmp(format,"darshan-recovery-target-native-engine-inspection-v4")||!next(&p,end,"operation=",op,sizeof(op))||!next(&p,end,"role=",r,sizeof(r))||!next(&p,end,"operation_id=",v->operation_id,37)||!next(&p,end,"target_handle=",v->target_handle,128)||!next_u64(&p,end,"generation=",&v->generation)||!next(&p,end,"command_semantic_sha256=",v->command_semantic_sha256,65)||!next(&p,end,"command_wire_sha256=",v->command_wire_sha256,65)||!next(&p,end,"command_nonce=",v->command_nonce,33)||!next(&p,end,"authority_instance_sha256=",v->authority_instance_sha256,65)||!next_u64(&p,end,"supervisor_generation=",&v->supervisor_generation)||!next(&p,end,"challenge_nonce=",v->challenge_nonce,33)||!next(&p,end,"materialization_head_sha256=",v->materialization_head_sha256,65)||!next(&p,end,"asset_manifest_sha256=",v->asset_manifest_sha256,65)||!next(&p,end,"daemon_identity_sha256=",v->daemon_identity_sha256,65)||!next(&p,end,"daemon_response_sha256=",v->daemon_response_sha256,65)||!next(&p,end,"observation_complete=",complete,sizeof(complete))||strcmp(complete,"true")||!next(&p,end,"absence_reliable=",absence,sizeof(absence))||(strcmp(absence,"true")&&strcmp(absence,"false"))||!next_u64(&p,end,"containers_count=",&v->containers_count)||!next_u64(&p,end,"networks_count=",&v->networks_count)||!next_u64(&p,end,"consumers_count=",&v->consumers_count)||!next(&p,end,"network_projection_sha256=",v->network_projection_sha256,65)||!next(&p,end,"postgres_projection_sha256=",v->postgres_projection_sha256,65)||!next(&p,end,"minio_projection_sha256=",v->minio_projection_sha256,65)||p!=end||!parse_operation(op,r,&v->operation,&v->role)){errno=EPROTO;return-1;}v->observation_complete=1;v->absence_reliable=!strcmp(absence,"true");if(!valid_inspection(v)){errno=EPROTO;return-1;}return 0;}
int rtew_encode_inspection_v4(const struct rtew_inspection_v4 *v,void *bytes,size_t capacity,size_t *size){if(!bytes||!size||!valid_inspection(v)){errno=EINVAL;return-1;}int n=snprintf(bytes,capacity,"format=darshan-recovery-target-native-engine-inspection-v4\noperation=%s\nrole=%s\noperation_id=%s\ntarget_handle=%s\ngeneration=%llu\ncommand_semantic_sha256=%s\ncommand_wire_sha256=%s\ncommand_nonce=%s\nauthority_instance_sha256=%s\nsupervisor_generation=%llu\nchallenge_nonce=%s\nmaterialization_head_sha256=%s\nasset_manifest_sha256=%s\ndaemon_identity_sha256=%s\ndaemon_response_sha256=%s\nobservation_complete=true\nabsence_reliable=%s\ncontainers_count=%llu\nnetworks_count=%llu\nconsumers_count=%llu\nnetwork_projection_sha256=%s\npostgres_projection_sha256=%s\nminio_projection_sha256=%s\n",operation(v->operation),role(v->role),v->operation_id,v->target_handle,(unsigned long long)v->generation,v->command_semantic_sha256,v->command_wire_sha256,v->command_nonce,v->authority_instance_sha256,(unsigned long long)v->supervisor_generation,v->challenge_nonce,v->materialization_head_sha256,v->asset_manifest_sha256,v->daemon_identity_sha256,v->daemon_response_sha256,v->absence_reliable?"true":"false",(unsigned long long)v->containers_count,(unsigned long long)v->networks_count,(unsigned long long)v->consumers_count,v->network_projection_sha256,v->postgres_projection_sha256,v->minio_projection_sha256);if(n<=0||(size_t)n>=capacity||(size_t)n>RTEW_V4_MAX_BYTES){errno=EMSGSIZE;return-1;}*size=(size_t)n;return 0;}
int rtew_inspection_wire_sha256_v4(const void *bytes,size_t size,char output[65]){struct rtew_inspection_v4 inspection;if(rtew_parse_inspection_v4(bytes,size,&inspection)<0)return-1;return hash_domain("darshan-recovery-target-native-engine-inspection-wire-v4",bytes,size,output);}
